return {Active=true,Revision=\"GarageApplication\"}\n\nend\nreturn Client\n","after":"local Catalog=require(game:GetService(\"ReplicatedStorage\").Modules.Game.Vehicles.VehicleCatalog)\n-- Current garage application; ClientBase owns startup.\nlocal Client={}\nlocal started=false\nfunction Client.start()\nif started then return end\nstarted=true\n-- Canonical feature implementation; startup is owned by the composition root.\nlocal Players=game:GetService(\"Players\"); local RS=game:GetService(\"ReplicatedStorage\"); local RunService=game:GetService(\"RunService\"); local Workspace=game:GetService(\"Workspace\")\nlocal player=Players.LocalPlayer; local kit=game:GetService(\"ReplicatedStorage\"); local categoriesRoot=game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Assets\"):WaitForChild(\"VehiclePreviews\"):WaitForChild(\"Categories\")\nlocal uiFolder=game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"UI\"); local intro=game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"Dealership\"); local previewFolder=game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"Garage\")\nlocal Browser=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"UI\"):WaitForChild(\"GarageBrowserUI\")); local WorkspaceUI=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"UI\"):WaitForChild(\"GarageWorkspaceUI\")); local Shared=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"UI\"):WaitForChild(\"GarageComponents\")); local ModuleCards=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"UI\"):WaitForChild(\"GarageModuleCardViewModel\")); local replacementConfig=game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Config\"):WaitForChild(\"UI\"):WaitForChild(\"GarageReplacement\")\nlocal garageInvoke=game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Remotes\"):WaitForChild(\"Garage\"):WaitForChild(\"GarageInvoke\")\nlocal sessionRequest=game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Remotes\"):WaitForChild(\"UI\"):WaitForChild(\"GarageSessionRequest\")\nlocal loadingInvoke=game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"UI\"):WaitForChild(\"LoadingTransitionInvoke\") \nlocal AudioBridge=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Audio\"):WaitForChild(\"PresentationAudioBridge\"))\nlocal ACTION_AUDIO_KIND={BuyCockpitInstance=\"Purchase\",BuyGarageProperty=\"Purchase\",BuyModuleInstance=\"Purchase\",BuyNeon=\"Purchase\",BuyVehicleCosmetic=\"Purchase\",EquipModuleInstance=\"ModuleEquip\",UpgradeModule=\"Upgrade\"}\nlocal Adapter={}; Adapter.__index=Adapter\nfunction Adapter.new(state) return setmetatable({State=state,Busy=false},Adapter) end\nfunction Adapter:Call(actionName,payload)\n\tlocal audioKind=ACTION_AUDIO_KIND[actionName]\n\tif self.Busy then local result={Success=false,Message=\"Please wait.\"}; if audioKind then AudioBridge.Result(audioKind,result,{Action=actionName}) end; return result end\n\tself.Busy=true; local ok,result=pcall(function() return garageInvoke:InvokeServer(actionName,payload or {}) end); self.Busy=false\n\tif not ok or typeof(result)~=\"table\" then result={Success=false,Message=\"Garage server did not respond.\"}; if audioKind then AudioBridge.Result(audioKind,result,{Action=actionName}) end; return result end\n\tif result.Catalog then self.State.Catalog=result.Catalog end; if result.Profile then self.State.Profile=result.Profile end; self.State.Economy=Shared.ProjectEconomy(result,self.State.Economy)\n\tlocal outcomeAudioKind=audioKind\n\tif result.Success==true then\n\t\tif actionName==\"BuyModuleInstance\" then outcomeAudioKind=\"ModuleEquip\"\n\t\telseif actionName==\"BuyCockpitInstance\" then outcomeAudioKind=\"VehiclePurchase\" end\n\tend\n\tif outcomeAudioKind then AudioBridge.Result(outcomeAudioKind,result,{Action=actionName}) end\n\treturn result\nend\nfunction Adapter:Refresh() return self:Call(\"GetInitial\",{}) end\nfunction Adapter:Session(actionName,payload) local ok,result=pcall(function() return sessionRequest:InvokeServer(actionName,payload or {}) end); return ok and result or {Success=false,Message=\"Garage session did not respond.\"} end\nfunction Adapter:NewModuleId(before,moduleId)\n\tlocal old={}; for id in pairs((before and before.OwnedModuleInstances) or {}) do old[id]=true end\n\tfor id,item in pairs((self.State.Profile and self.State.Profile.OwnedModuleInstances) or {}) do if not old[id] and tostring(item.TemplateId)==tostring(moduleId) then return id end end\nend\n\nlocal PreviewVehicle=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Garage\"):WaitForChild(\"PreviewVehicleClient\")); local PreviewCamera=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Garage\"):WaitForChild(\"PreviewCameraClient\")); local InstancePreview=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Garage\"):WaitForChild(\"GarageModuleInstancePreviewAdapter\")); local PreviewProfiles=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Garage\"):WaitForChild(\"GarageVehiclePreviewProfile\")) \nlocal performance=game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Vehicles\"):WaitForChild(\"Performance\"); local PerformanceResolver=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"V