owCash,OnCapacity=showProperties,ExitVisible=false,Legacy={}} end\nlocal function driveFromGarage()\n\tlocal engine,stabilisers,boost=coreReady(); if not(engine and stabilisers and boost) then message(\"Equip one engine, stabilisers, and boost before driving.\"); return end\n\tlocal generation=loadingAction(\"Begin\",{Destination=\"FreeRoamDrive\",Status=\"PREPARING VEHICLE\"})\n\tclearTransientModulePreview()\n\tlocal ended=action:Session(\"End\",{ReturnToEntry=true})\n\tif not ended or ended.Success~=true then local reason=(ended and ended.Message) or \"Could not leave customisation.\"; loadingAction(\"Fail\",{Generation=generation,Status=\"RETURNING\",Reason=reason}); message(reason); return end\n\tlocal result=action:Call(\"SpawnVehicle\",{})\n\tif not result.Success then local reason=result.Message or \"Vehicle spawn failed\"; active=false; hideAll(); closeCamera(); player:SetAttribute(\"GarageEntryMode\",nil); local failedEvent=game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"Dealership\"):FindFirstChild(\"GarageClosedFromDealershipExit\"); if failedEvent and failedEvent:IsA(\"BindableEvent\") then failedEvent:Fire() end; loadingAction(\"Fail\",{Generation=generation,Status=\"RETURNING\",Reason=reason}); warn(\"[Canonical Garage] Drive exit failed safely: \"..tostring(reason)); return end\n\tactive=false; hideAll(); closeCamera(); player:SetAttribute(\"GarageEntryMode\",nil); fire(\"FreeRoamVehicleSpawned\"); local event=game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"Dealership\"):FindFirstChild(\"GarageClosedFromDealershipExit\"); if event and event:IsA(\"BindableEvent\") then event:Fire() end\n\tloadingAction(\"Complete\",{Generation=generation,Status=\"READY TO DRIVE\"})\nend\nrenderBrowser=function()\n\tState.Stage=\"Browser\"; setPreviewVFXMode(\"Idle\"); hideAll(); local owned,cap=capacity(); browser:Show({Mode=State.ShopMod