try=true}); if not ended or ended.Success~=true then local reason=(ended and ended.Message) or \"Could not leave garage.\"; loadingAction(\"Fail\",{Generation=generation,Status=\"RETURNING\",Reason=reason}); message(reason); return end; active=false; hideAll(); closeCamera(); player:SetAttribute(\"GarageEntryMode\",nil); local e=game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"Dealership\"):FindFirstChild(\"GarageClosedFromDealershipExit\"); if e and e:IsA(\"BindableEvent\") then e:Fire() end; loadingAction(\"Complete\",{Generation=generation,Status=\"READY\"}) end,OnCash=showCash,OnCapacity=showProperties})\nend\nrenderPaint=function()\n\tif State.CameraSection~=\"ALL\" then section(\"ALL\") end\n\tState.Stage=\"Paint\"; browser:Hide(); local c=common(\"Paint Vehicle\"); c.Subtitle=\"Choose a whole-vehicle colour, then continue to your garage.\"; c.ShowLeft=false; c.BackVisible=false; c.NextText=\"Customise\"; c.NextIcon=navIcon(\"CustomiseIcon\"); c.NextIconText=\"*\"; c.ColorChannels={\"Primary\",\"Secondary\",\"Detail\"}; c.SelectedChannel=State.SelectedColorChannel; c.Colors=State.Profile.CockpitColors or {}; c.OnChannel=function(ch) State.SelectedColorChannel=ch; renderPaint() end; c.OnColor=function(ch,color,commit) handlePaint(\"WholeVehicle\",ch,color,commit) end; c.OnNext=function() clearTransientModulePreview(); renderHub() end; workspaceUI:Show(c)\nend\nrenderHub=function()\n\tif State.CameraSection~=\"ALL\" then section(\"ALL\") end\n\tState.Stage=\"Hub\"\n\tbrowser:Hide()\n\tlocal c=common(\"Garage\"); c.TutorialPageId=\"CustomisationHome\" \n\tc.CarouselScrollKey=\"Hub|ThreeWorkshops\"\n\tc.Subtitle=\"Choose a workshop, or drive your vehicle.\"\n\tc.ShowLeft=false\n\tc.BackVisible=false\n\tc.NextText=\"Drive\"\n\tc.NextIcon=navIcon(\"DriveIcon\")\n\tc.NextIconText=\">\"\n\tc.Cards={\n\t\t{Id=\"AddModules\",Image=navIcon(\"BuildModulesIcon\"),ImageZoom=.5,DisplayName=\"Add Modules\",OnSel