ionCatalog.Normalize(property.Customisation.Decorations,definition.DecorationSlots); local colors=type(args.Colors)==\"table\" and args.Colors or {}; if not (session and decorationsState) then return {Success=false,Message=\"Decoration finish preview is invalid.\"} end; local previews={}; for _,slot in ipairs(definition.DecorationSlots or {}) do local slotId=tostring(slot.SlotId or \"\"); local placement=decorationsState.Placements[slotId]; local item=placement and decorationCatalog.ById(placement.ItemId); local asset=item and finishRuntime.DecorationAsset(definition.TemplateId,slotId,item.AssetName,item.AssetGroupId or slot.AssetGroupId); local capability=asset and finishRuntime.Inspect(asset,\"Decoration\"); if capability then local targetColors={}; for channel,value in pairs(colors) do if table.find(capability.ColourChannels or {},channel) then targetColors[channel]=value end end; if next(targetColors) then local valid,message=finishRuntime.ValidateDecorationFinish(definition.TemplateId,item,targetColors); if not valid then return {Success=false,Message=message} end; local preview={SlotId=slotId,ItemId=item.ItemId,Colors=clone(placement.Colors)}; for channel,value in pairs(targetColors) do preview.Colors[channel]=value end; previews[slotId]=preview end end end; if next(previews)==nil then return {Success=false,Message=\"No installed decoration supports this colour.\"} end; session.DecorationPreview=nil; session.DecorationPreviewAll=previews; local rendered,renderMessage=applyDecorations(profile,session); return {Success=rendered==true,Message=renderMessage or \"All-decoration preview ready.\"}\n\t\t\telseif action==\"CancelDecorationPreview\" then local session=sessions[player]; if not session then return {Success=false,Message=\"Garage session is not active.\"} end; if not session.DecorationPreview and not session.DecorationPreviewAll then return {Success=true,NoChange=true,Message=\"No decoration preview was active.\"} end; session.DecorationPreview=nil; sessio